const phone = $('Webhook').first().json.body?.from || '';
const airtableItem = $input.first().json;
// Airtable search returns fields at top level (not nested under .fields)
const customer = airtableItem.id ? airtableItem : null;

const fieldMap = [
  ['Nationality', 'nationality'],
  ['Age', 'age'],
  ['Marital Status', 'marital status'],
  ['Number of Children', 'number of children'],
  ['Net Salary', 'net salary'],
  ['Budget', 'budget'],
  ['Timeline', 'timeline'],
  ['Mortgage Status', 'mortgage status'],
  ['Property Type', 'property type'],
  ['Preferred Areas', 'preferred areas']
];

if (!customer) {
  return [{ json: {
    customer_first_name: 'there',
    is_returning_caller: 'no',
    known_data: 'none',
    missing_fields: fieldMap.map(f => f[1]).join(', ')
  }}];
}

const missing = [];
const known = [];

for (const [field, label] of fieldMap) {
  const val = customer[field];
  const isEmpty = val === null || val === undefined || val === '' || val === 0;
  if (isEmpty) {
    missing.push(label);
  } else {
    known.push(`${label}: ${val}`);
  }
}

const firstName =
  customer['First Name'] ||
  (customer['Name'] ? customer['Name'].split(' ')[0] : '') ||
  'there';

return [{ json: {
  customer_first_name: firstName,
  is_returning_caller: 'yes',
  known_data: known.length > 0 ? known.join(', ') : 'none',
  missing_fields: missing.length > 0 ? missing.join(', ') : 'none'
}}];
